import { ViewTransition } from 'react'

const directionalTransition = {
  'nav-forward': 'nav-forward',
  'nav-back': 'nav-back',
  default: 'none',
} as const

export function PageTransition({ children }: { children: React.ReactNode }) {
  return (
    <ViewTransition
      enter={directionalTransition}
      exit={directionalTransition}
      default="none"
    >
      {children}
    </ViewTransition>
  )
}

